refsection.programlisting:
scicv_Init();

// Create an image
img = new_Mat();
disp("Is a new image empty ?");
disp(Mat_empty(img));
delete_Mat(img);

// Load an image and give its dimensions
disp("Load Lena image...");
img = imread("data/images/lena.jpg");

disp("Image type:");
disp(getImageType(img));

disp("Number of cols:");
disp(Mat_cols_get(img));

disp("Number of rows:");
disp(Mat_rows_get(img));

delete_Mat(img);
